        vars['card_question'] = 'Hangi kartınızın borcunu öğrenmek istersiniz? Kartınızın son dört hanesini söyleyebilirsiniz.'
    if len(mains) == 1 and len(nums) == 1:
        vars['cards_state'] = 'one'
        vars['selected_card'] = mains[0]
    elif mains:
        vars['cards_state'] = 'multi'
    elif nums or any('FB_IVR_CHANNEL_102' in str(v) for v in list(vars.values())):
