import datetime, re
B = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
O = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
MO = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
DG = ['sıfır'] + B[1:]
NM = dict(TL='Türk Lirası', USD='Dolar', EUR='Euro', GBP='İngiliz Sterlini')
SUB = dict(TL='kuruş', USD='sent', EUR='sent', GBP='peni')
CUR = ['TL', 'USD', 'EUR', 'GBP']
def w3(n):
    h, r = divmod(n, 100)
    s = []
    if h:
        s.append('yüz' if h == 1 else B[h] + ' yüz')
    if r // 10:
        s.append(O[r // 10])
    if r % 10:
        s.append(B[r % 10])
    return ' '.join(s)
def words(n):
    if n == 0:
        return 'sıfır'
    s = []
    for v, nm in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, v)
        if q:
            s.append('bin' if v == 1000 and q == 1 else w3(q) + ' ' + nm)
    if n:
        s.append(w3(n))
    return ' '.join(s)
def g(k):
    try:
        return float(str(vars.get(k)).strip())
    except Exception:
        return None
def amt(x, c):
    a, k = divmod(int(round(abs(x) * 100)), 100)
    return words(a) + ' ' + NM[c] + (' ' + words(k) + ' ' + SUB[c] if k else '')
def pd(s):
    try:
        d, m, y = str(s).strip().split('.')
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None
def sd(d):
    return '%d %s %d' % (d.day, MO[d.month], d.year)
def jn(a):
    return a[0] if len(a) == 1 else ', '.join(a[:-1]) + ' ve ' + a[-1]
try:
    try:
        today = datetime.date.fromisoformat(str(vars.get('now'))[:10])
    except Exception:
        today = None
    l4 = re.sub(r'\D', '', str(vars.get('b_last4') or ''))[-4:]
    name = str(vars.get('b_name') or '').strip()
    if len(name) > 40 or len(name.split()) > 4:
        name = ''
    label = 'Sonu ' + ' '.join(DG[int(c)] for c in l4) + ' ile biten' + (' ' + name if name else '')
    s_d, l_d, n_d = pd(vars.get('b_sd')), pd(vars.get('b_lpd')), pd(vars.get('b_nsd'))
    present = [c for c in CUR if g('b_' + c + '_rd') is not None]
    debt = [c for c in present if g('b_' + c + '_rd') > 0]
    clear = [c for c in present if c not in debt]
    tot = [amt(g('b_' + c + '_td'), c) for c in present if (g('b_' + c + '_td') or 0) > 0]
    mode = 'normal'
    if s_d is None:
        mode = 'no_debt'
        t = label + ' kartınızın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.'
        if n_d:
            t += ' İlk hesap kesim tarihiniz ' + sd(n_d) + ' olacak.'
    elif today and (n_d == today or s_d == today):
        t = 'Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek. ' + label + ' kartınızın harcamalar dahil güncel toplam borcu ' + (jn(tot) + '.' if tot else 'bulunmamaktadır.')
    elif debt and today and l_d and today > l_d:
        t = label + ' kartınızın ' + sd(s_d) + ' tarihli ekstresinin son ödeme tarihi olan ' + sd(l_d) + ' geçmiştir. Güncel toplam borcunuz ' + (jn(tot) + '.' if tot else 'bulunmamaktadır.')
        ap = g('b_TL_ap') or 0
        if str(vars.get('b_apf')) == 'Y' and ap > 0:
            t += ' Otomatik ödeme talimatınızdan alınacak kalan tutar ' + amt(ap, 'TL') + '.'
    elif str(vars.get('b_sps')) == 'NO_DEBT' or not debt:
        mode = 'no_debt'
        ttl = g('b_TL_td') or 0
        t = label + ' kartınızın ' + sd(s_d) + ' tarihli ekstresinden borcunuz bulunmamaktadır. ' + ('Gelecek dönemler dahil toplam borcunuz ' + amt(ttl, 'TL') + '.' if ttl > 0 else 'Gelecek dönemler dahil bir borcunuz bulunmamaktadır.')
        if l_d and not (today and today > l_d):
            t += ' Son ödeme tarihiniz ' + sd(l_d) + ' olacaktır.'
    else:
        parts = []
        for c in debt:
            x, mp, rd, rm = g('b_' + c + '_sd') or 0, g('b_' + c + '_mp') or 0, g('b_' + c + '_rd'), g('b_' + c + '_rm') or 0
            if c != 'TL':
                parts.append(NM[c] + ' borcunuz ' + amt(x, c) + ', kalan toplam borcunuz ' + amt(rd, c) + ', ödenmesi gereken minimum tutar ' + amt(mp, c) + '.')
            elif rm <= 0:
                parts.append('Türk Lirası borcunuz ' + amt(x, c) + ', kalan toplam borcunuz ' + amt(rd, c) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.')
            elif rm >= mp:
                parts.append('Türk Lirası borcunuz ' + amt(x, c) + ', ödenmesi gereken minimum tutar ' + amt(mp, c) + '.')
            else:
                parts.append('Türk Lirası borcunuz ' + amt(x, c) + ', ödenmesi gereken minimum tutar ' + amt(mp, c) + ', kalan toplam borcunuz ' + amt(rd, c) + ', kalan minimum ödeme tutarınız ' + amt(rm, c) + '.')
        t = label + ' kartınıza ait ' + sd(s_d) + ' tarihinde kesilen ekstre ' + ' '.join(parts)
        if clear:
            t += ' ' + jn([NM[c] for c in clear]) + ' borcunuz bulunmamaktadır.'
        if l_d:
            t += ' Borçlarınız için son ödeme tarihiniz ' + ('bugündür.' if l_d == today else sd(l_d) + '.')
    nums = [n for n in str(vars.get('card_numbers') or '').split('|') if n]
    sel = ''
    for k, v in list(vars.items()):
        if str(k).startswith('cards_balance_args') and str(v) in nums:
            sel = str(v)
    if not sel:
        bc = str(vars.get('b_card') or '')
        for n in nums:
            if n[:4] == bc[:4] and n[-4:] == bc[-4:]:
                sel = n
    if sel:
        vars['selected_card'] = sel
    done = [x for x in str(vars.get('read_cards') or '').split(',') if x]
    if (sel or l4) not in done:
        done.append(sel or l4)
    vars['read_cards'] = ','.join(done)
    oq = 'Başka bir kartınızın borcunu öğrenmek ister misiniz?' if int(g('card_count') or 1) > len(done) else ''
    if mode == 'no_debt':
        off = ''
    elif str(vars.get('email_state')) == 'ok':
        off = 'Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim.'
    else:
        off = 'Hesap kesim tarihinizi değiştirebilirim.'
    vars['debt_text'] = t
    vars['card_label'] = label
    vars['debt_mode'] = mode
    vars['other_card_question'] = oq
    vars['offer_text'] = off
    vars['opening_text'] = (t + ' ' + (oq or off)).strip()
    vars['end_after_read'] = 'yes' if mode == 'no_debt' and not oq else 'no'
except Exception:
    vars['debt_mode'] = 'error'
    vars['end_after_read'] = 'no'

